    {
        var options = (IDiginsightActivitiesOptions)_optionsMonitor.CurrentValue;

        return Ok(new
        {
            patterns = options.ActivitySources.ToDictionary(
                kvp =&gt; kvp.Key,
                kvp =&gt; kvp.Value ? "included" : "excluded")
        });
    }
